window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dbbf6bdbe0346f09"]={"versions": [{"id": "FIG-dbbf6bdbe0346f09", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsdiagramm bzw. Lebenszyklusdiagramm einer Anwendung (Application States) innerhalb der AUTOSAR Adaptive Platform im Kontext des Execution Management (SWS ExecutionManagement). Das Diagramm veranschaulicht die internen Phasen eines Prozesses von der Instanziierung bis zur Terminierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialer Kontext / Vorstufe (Ellipse)</strong>: <code>create process allocate resources</code> – Betriebssystem- bzw. EM-Aktivität zur Prozesserzeugung und Ressourcenbereitstellung außerhalb des regulären Anwendungslebenszyklus.</li>\n<li><strong>Anwendungszustände (Rechteckboxen innerhalb des Hauptrahmens)</strong>:</li>\n<li><code>Initializing</code>: Phase für Anwendungs- und Dateninitialisierung (<code>application data initialization</code>).</li>\n<li><code>Running</code>: Phase zur Ausführung der Hauptfunktionalität (<code>perform main functionality</code>).</li>\n<li><code>Terminating</code>: Phase für Aufräumarbeiten wie Datenspeicherung, Ressourcenfreigabe und Beendigung (<code>store data, free resources, exit</code>).</li>\n<li><strong>Übergänge (Pfeile)</strong>:</li>\n<li>Ein einfacher gerichteter Pfeil vom Initialisierungsschritt in den Zustand <code>Initializing</code>.</li>\n<li>Ein breiter Blockpfeil von <code>Initializing</code> nach <code>Running</code>.</li>\n<li>Ein breiter, mit <code>Terminate</code> beschrifteter Blockpfeil von <code>Running</code> nach <code>Terminating</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Prozessstart</strong>: Das Execution Management erzeugt den Prozess und weist die benötigten Ressourcen zu (<code>create process allocate resources</code>).</li>\n<li><strong>Initialisierung</strong>: Der Prozess tritt in den Zustand <code>Initializing</code> ein, führt interne Daten- und Plattforminitialisierungen durch.</li>\n<li><strong>Regulärer Betrieb</strong>: Nach erfolgreicher Initialisierung wechselt der Prozess in den Zustand <code>Running</code> und führt seine eigentliche Applikationslogik aus.</li>\n<li><strong>Beendigung</strong>: Durch ein Terminate-Ereignis bzw. eine Terminate-Anforderung (<code>Terminate</code>) geht der Prozess in den Zustand <code>Terminating</code> über, sichert persistente Daten, gibt belegte Ressourcen frei und terminiert regulär (<code>exit</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Darstellung der High-Level-Zustände einer Adaptive Application. Adaptive Applications müssen diese Lebenszyklusphasen implementieren bzw. mit dem Execution Management interagieren (insbesondere ordnungsgemäße Zustandsmeldungen und Behandeln von Terminierungsanforderungen zur geordneten Ressourcenfreigabe).</p>"}, {"id": "FIG-b173f288f73d353b", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsdiagramm bzw. Lebenszyklusdiagramm einer Anwendung (Application States) innerhalb der AUTOSAR Adaptive Platform im Kontext des Execution Management (SWS ExecutionManagement). Das Diagramm veranschaulicht die internen Phasen eines Prozesses von der Instanziierung bis zur Terminierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialer Kontext / Vorstufe (Ellipse)</strong>: <code>create process allocate resources</code> – Betriebssystem- bzw. EM-Aktivität zur Prozesserzeugung und Ressourcenbereitstellung außerhalb des regulären Anwendungslebenszyklus.</li>\n<li><strong>Anwendungszustände (Rechteckboxen innerhalb des Hauptrahmens)</strong>:</li>\n<li><code>Initializing</code>: Phase für Anwendungs- und Dateninitialisierung (<code>application data initialization</code>).</li>\n<li><code>Running</code>: Phase zur Ausführung der Hauptfunktionalität (<code>perform main functionality</code>).</li>\n<li><code>Terminating</code>: Phase für Aufräumarbeiten wie Datenspeicherung, Ressourcenfreigabe und Beendigung (<code>store data, free resources, exit</code>).</li>\n<li><strong>Übergänge (Pfeile)</strong>:</li>\n<li>Ein einfacher gerichteter Pfeil vom Initialisierungsschritt in den Zustand <code>Initializing</code>.</li>\n<li>Ein breiter Blockpfeil von <code>Initializing</code> nach <code>Running</code>.</li>\n<li>Ein breiter, mit <code>Terminate</code> beschrifteter Blockpfeil von <code>Running</code> nach <code>Terminating</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Prozessstart</strong>: Das Execution Management erzeugt den Prozess und weist die benötigten Ressourcen zu (<code>create process allocate resources</code>).</li>\n<li><strong>Initialisierung</strong>: Der Prozess tritt in den Zustand <code>Initializing</code> ein, führt interne Daten- und Plattforminitialisierungen durch.</li>\n<li><strong>Regulärer Betrieb</strong>: Nach erfolgreicher Initialisierung wechselt der Prozess in den Zustand <code>Running</code> und führt seine eigentliche Applikationslogik aus.</li>\n<li><strong>Beendigung</strong>: Durch ein Terminate-Ereignis bzw. eine Terminate-Anforderung (<code>Terminate</code>) geht der Prozess in den Zustand <code>Terminating</code> über, sichert persistente Daten, gibt belegte Ressourcen frei und terminiert regulär (<code>exit</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Darstellung der High-Level-Zustände einer Adaptive Application. Adaptive Applications müssen diese Lebenszyklusphasen implementieren bzw. mit dem Execution Management interagieren (insbesondere ordnungsgemäße Zustandsmeldungen und Behandeln von Terminierungsanforderungen zur geordneten Ressourcenfreigabe).</p>"}], "trans": [{"from": "FIG-dbbf6bdbe0346f09", "to": "FIG-b173f288f73d353b", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
